import type { CallToolResult, McpServer, ToolAnnotations } from "@modelcontextprotocol/server";
import { z } from "zod";
import { registerSemanticApiTools } from "../../vendor/semantic_api_tools.mjs";
import { connectorHostname } from "../config";
import type { ResolvedGraph } from "../graphs";
import { SyncError, type SyncRequest, syncFetch } from "../sync";
import { ToolError, aliasArg, runTool } from "./common";
import { ALIAS_PATTERN, type GraphOperation, type OpenApiSpec, graphOperations, transformSpec } from "./spec.mjs";

// One MCP tool per sync-server operation, generated by upstream's `registerSemanticApiTools` from the
// transformed spec. Upstream substitutes the `graph` alias into the path; `request` below maps it to
// the graph's ID and PAT, enforces read-only graphs and calls the sync server over the SYNC binding.
// Building the tools (JSON Schema → zod) is the expensive part, so it happens once per isolate
// (`buildGraphTools`); each request only registers the built tools on its own fresh server.

export interface GraphAccess {
  env: Env;
  /** The graph behind an alias, read in one query; null for an unknown alias. */
  resolve(alias: string): Promise<ResolvedGraph | null>;
}

/** A generated tool, ready to register. Its handler throws `ToolError` for refusals and mapped errors. */
export interface GraphTool {
  name: string;
  config: { description: string; inputSchema: z.ZodObject<z.ZodRawShape>; annotations: ToolAnnotations };
  handler: UpstreamHandler;
}

/** What upstream's tool handlers pass to `request`: the path already has every argument substituted. */
interface UpstreamRequest {
  method: string;
  path: string;
  query?: Record<string, unknown>;
  body?: unknown;
}

type UpstreamHandler = (args: Record<string, unknown>) => Promise<CallToolResult>;

const ALIAS = new RegExp(ALIAS_PATTERN);
const GRAPH_PATH = /^\/api\/v1\/graphs\/([^/]+)(\/.*)$/;
const DEFAULT_RETRY_AFTER_S = 60;

/** Usage conventions added to the generated descriptions of the tools they concern. */
const HINTS: Record<string, string> = {
  insert_block_tree:
    "Prefer this for whole notes such as meeting notes: one write call instead of many (writes are rate-limited).",
  create_task: "Use this for every task or action item.",
  create_property:
    "Give a property its choices when creating it (choices: [{title, icon?, description?}], in the order the editor should list them); choices are for default (text), number and url properties. Give a node property its classes when creating it (classes: tag UUIDs, idents or titles), so the app's picker and every value write accept only objects of those tags. The response lists each choice's UUID.",
  update_property:
    "Change a property's choices with choices.add, choices.update and choices.order, in one call: add puts new choices after the existing ones; update renames, re-icons or describes a choice named by UUID, ident or title (icon: null clears its icon); order lists every choice once, including ones added in the same call, each by the title the call leaves it with (a title a rename frees and an add takes names the new choice). A rename may take a title another rename in the same call gives up, in any order, but renames that pass titles round a cycle (a swap) are refused: rename one to a spare title in a separate call first. A title already a choice (ignoring case) is refused, and the response lists every choice's UUID. choices.retire removes choices; blocks that hold one would lose the value, so a retire with holders, or of the choice that is the property's default value (which retiring clears, so blocks relying on the default stop showing it), is refused (409, with each choice's holder count and default: true for the default) unless acknowledge-holders is true: run it with dry-run first, show the user the counts, and only acknowledge a loss the user agreed to. order then lists only the surviving choices; built-in choices (Status, Priority) can't be retired. To restrict a node property to classes, give classes exactly one of set, add or remove (each a list of tag UUIDs, idents or titles); {set: []} clears the restriction. Existing values are kept: out_of_class counts the holders whose value the classes would now refuse (holders left empty aren't counted). A built-in property's classes, such as Assignee's, can't be changed. convert_values: true turns a free-text (default) property into a choice property: each distinct text becomes the choice it names (exactly, then ignoring case), every holder is re-pointed at it and the old text values are deleted. Text that matches no choice refuses the whole call and is listed, so add those choices under choices.add in the same call; a property with a default value, or a text value with child blocks, is refused (the children would be deleted), and empty placeholder values are left alone; dry-run shows the mapping (each text, its choice and its holder count) first. Don't change type in the same call.",
  create_tag:
    "Give the tag its extends and properties in the same call (tag and property UUIDs, idents or titles), so it is set up in one write. Built-in tags such as Tag, Page, Journal, Query and Template can't be extended.",
  promote_page_to_tag:
    "Turns an existing page into a tag in place: its UUID, blocks, properties and references are kept, and links to it stay links (they aren't tagged). Run with dry-run first on a page with many references and show the user the counts. Give extends to set the tags it extends in the same call (tag UUIDs, idents or titles; built-in tags such as Tag and Page, and the page itself, are refused). Refuses journals, built-ins, properties, namespaced pages and existing tags. Setting a page's tags to Tag is refused; use this instead.",
  update_tag:
    "To change one tag property and keep the rest, use properties.add or properties.remove; properties.set replaces the tag's own properties (built-in ones stay). extends replaces the tags it extends; built-in tags such as Tag, Page, Journal, Query and Template can't be extended. title is optional.",
};

function description(op: GraphOperation): string {
  const parts = [op.operation.summary ?? `${op.method} ${op.path}`];
  if (op.operation.description) parts.push(op.operation.description);
  if (HINTS[op.name]) parts.push(HINTS[op.name]);
  return parts.join("\n\n");
}

function syncErrorText(error: SyncError, alias: string, host: string): string {
  if (error.status === 401 || error.status === 403) {
    return `token for graph '${alias}' expired or lacks permission — reconnect it at https://${host}/graphs`;
  }
  if (error.status === 429) return `rate limited — retry after ${error.retryAfter ?? DEFAULT_RETRY_AFTER_S} s`;
  // 409 is a refusal the caller can act on, e.g. a title already in use or a delete that needs an
  // acknowledge-* flag; the server's message says what to do.
  if (error.status === 400 || error.status === 409) return error.message;
  return `sync server error (HTTP ${error.status}): ${error.message}`;
}

function queryParams(query: Record<string, unknown> | undefined): Record<string, string | number | boolean> | undefined {
  if (query === undefined) return undefined;
  const out: Record<string, string | number | boolean> = {};
  for (const [key, value] of Object.entries(query)) {
    if (typeof value !== "string" && typeof value !== "number" && typeof value !== "boolean") {
      throw new Error(`query parameter ${key} is not a scalar`);
    }
    out[key] = value;
  }
  return out;
}

/**
 * The graph behind `alias` for one tool call. Throws `ToolError` for an unknown alias, and for a
 * write on a read-only graph, before anything reaches the sync server.
 */
export async function resolveGraph(access: GraphAccess, alias: string, write: boolean): Promise<ResolvedGraph> {
  const graph = await access.resolve(alias);
  if (!graph) {
    throw new ToolError(`unknown graph '${alias}' — call list_graphs for the connected aliases`, "unknown-graph");
  }
  if (graph.mode !== "read" && graph.mode !== "write") throw new Error(`graph '${alias}' has an invalid mode`);
  if (graph.mode === "read" && write) throw new ToolError(`graph '${alias}' is read-only`, "read-only");
  return graph;
}

/** `syncFetch` for a tool call on `alias`: a sync server error becomes a `ToolError` with clear text. */
export async function graphFetch(access: GraphAccess, alias: string, pat: string, req: SyncRequest): Promise<Response> {
  try {
    return await syncFetch(access.env, pat, req);
  } catch (error) {
    if (!(error instanceof SyncError)) throw error;
    throw new ToolError(syncErrorText(error, alias, connectorHostname(access.env)), `http-${error.status}`);
  }
}

async function request(access: GraphAccess, req: UpstreamRequest): Promise<unknown> {
  const match = GRAPH_PATH.exec(req.path);
  // Upstream builds the path from the transformed spec, and the input schema enforces the alias pattern.
  if (!match || !ALIAS.test(match[1])) throw new Error("generated tool produced an unexpected path");
  const [, alias, rest] = match;
  for (const segment of rest.slice(1).split("/")) {
    if (segment === "") throw new ToolError("path arguments may not be empty", "refused");
    // Upstream percent-encodes each argument but leaves `.` and `..` as they are, and URL parsing
    // would collapse those into a different route.
    if ([".", ".."].includes(decodeURIComponent(segment))) {
      throw new ToolError("path arguments may not be '.' or '..'", "refused");
    }
  }
  const graph = await resolveGraph(access, alias, req.method !== "GET");
  const response = await graphFetch(access, alias, graph.pat, {
    method: req.method,
    path: `/api/v1/graphs/${encodeURIComponent(graph.graphId)}${rest}`,
    query: queryParams(req.query),
    json: req.body,
  });
  const text = await response.text();
  return text === "" ? null : JSON.parse(text);
}

/**
 * Builds one tool per graph operation of the sync server's OpenAPI `spec`. Nothing request-scoped is
 * captured: each call resolves its graph from the alias in its own path.
 */
export function buildGraphTools(spec: OpenApiSpec, access: GraphAccess): GraphTool[] {
  const operations = new Map(graphOperations(spec).map((op) => [op.operationId, op]));
  const tools = new Map<string, GraphTool>();
  // Upstream names each tool after its operationId and registers it on this recording proxy; the
  // recorded tool gets the snake_case name and the full description.
  const recorder = {
    registerTool(
      operationId: string,
      config: { inputSchema: z.ZodRawShape; annotations: ToolAnnotations },
      handler: UpstreamHandler,
    ): void {
      const op = operations.get(operationId);
      if (!op || tools.has(operationId)) throw new Error(`upstream registered an unexpected operation: ${operationId}`);
      tools.set(operationId, {
        name: op.name,
        config: {
          description: description(op),
          inputSchema: z.object(config.inputSchema),
          annotations: config.annotations,
        },
        handler,
      });
    },
  };
  registerSemanticApiTools(recorder, transformSpec(spec), (req: UpstreamRequest) => request(access, req));
  if (tools.size !== operations.size) throw new Error("upstream did not register every graph operation");
  return [...tools.values()];
}

/**
 * Registers built graph tools on one request's server, with the connector's logging, error mapping
 * and result cap. `onSuccess` runs after each call the sync server accepted.
 */
export function registerGraphTools(
  server: McpServer,
  tools: GraphTool[],
  onSuccess: (tool: string, alias: string) => void,
): void {
  for (const tool of tools) {
    server.registerTool(tool.name, tool.config, (args) => {
      const alias = aliasArg(args);
      return runTool(tool.name, alias, async () => {
        const result = await tool.handler(args);
        // The input schema requires a well-formed alias, so a call that got this far has one.
        if (alias === undefined) throw new Error("graph tool ran without a valid alias");
        onSuccess(tool.name, alias);
        return result;
      });
    });
  }
}
